806	// --- Record division --------------------------------------------------------
807	//
808	// This is the SINGLE place that maintains how a raw byte batch is divided into
809	// records. Both commands drive the same rule:
810	//
811	// - `prove` scans an already-read batch with [`RecordScanner::scan`], collecting
812	//   one slice per record ([`split_records`]);
813	// - `root` feeds its fixed-size read buffer chunk by chunk to the same
814	//   [`RecordScanner`] inside [`RootStream`], so a read boundary is never a
815	//   record boundary.
816	//
817	// The rule, byte for byte:
818	//
819	// - LF (0x0a) separates records and is never itself content. Every other byte
820	//   — CR, space, tab, NUL, a non-UTF-8 byte — is content delivered verbatim;
821	//   there is no text decoding, trimming or newline normalization.
822	// - A record comes into existence either by receiving content or by being
823	//   terminated with an LF. Leading and consecutive LFs therefore keep their
824	//   empty records; an empty input is zero records, while a single LF is one
825	//   empty record.
826	// - A trailing LF only terminates the record in progress and adds no empty
827	//   record; a final record without a trailing LF is the same record sequence.
828	//
829	// The division is expressed as an event sink ([`RecordSink`]) rather than as a
830	// returned list, so the streaming caller never has to accumulate a complete
831	// record or batch: `record_bytes` hands out sub-slices straight from the chunk
832	// being scanned.
833	
834	/// Receives the division of a byte stream into records from
835	/// [`RecordScanner`]. Every method sees raw bytes only; the scanner alone
836	/// decides *when* each event fires, so a sink never re-interprets LF or the
837	/// end of stream.
838	trait RecordSink {
839	    /// A non-empty run of content bytes belonging to the record currently in
840	    /// progress; the slice is borrowed from the chunk being scanned and must
841	    /// not be relied on after the call returns. One record arrives as any
842	    /// number of these runs (a long record spanning many chunks gets many),
843	    /// but an empty record gets none.
844	    fn record_bytes(&mut self, bytes: &[u8]);
845	
846	    /// One record was terminated by an LF (which is never delivered as
847	    /// content). Fires for every LF in the stream, including a leading LF and
848	    /// the second of two consecutive LFs — those close empty records.
849	    fn record_end(&mut self);
850	
851	    /// The stream ended right after content bytes with no terminating LF, so
852	    /// that content is itself the final record. Fires at most once, only when
853	    /// such content exists; after a bare trailing LF it does not fire.
854	    fn tail_end(&mut self);
855	}
