857	/// The shared record-boundary state machine. Independent of how the bytes are
858	/// obtained: one whole batch ([`RecordScanner::scan`]) or arbitrarily sized
859	/// chunks fed across reads ([`RecordScanner::feed`]) divide into exactly the
860	/// same record sequence. The only state it keeps is whether a content-only
861	/// record is open at the end of the last chunk, so nothing grows with the
862	/// number of records or their length.
863	struct RecordScanner<S: RecordSink> {
864	    sink: S,
865	    /// Content has arrived for the record currently in progress and no LF has
866	    /// closed it yet. Decides whether [`RecordSink::tail_end`] fires at end of
867	    /// stream — the one place the "trailing LF adds no record" rule lives.
868	    open: bool,
869	}
870	
871	impl<S: RecordSink> RecordScanner<S> {
872	    fn new(sink: S) -> Self {
873	        RecordScanner { sink, open: false }
874	    }
875	
876	    /// Feed the next chunk. Read boundaries fall inside content or on LF
877	    /// bytes; either way the division sees no boundary of its own — an LF split
878	    /// across two chunks still ends the record, and two LFs in adjacent chunks
879	    /// keep the empty record between them.
880	    fn feed(&mut self, chunk: &[u8]) {
881	        let mut rest = chunk;
882	        while let Some(pos) = rest.iter().position(|&b| b == b'\n') {
883	            // Content before this LF (nothing for a leading/consecutive LF);
884	            // the empty-run case must not look like content.
885	            if pos > 0 {
886	                self.sink.record_bytes(&rest[..pos]);
887	            }
888	            self.sink.record_end();
889	            rest = &rest[pos + 1..];
890	            self.open = false;
891	        }
892	        // Bytes after the last LF (or all of an LF-free chunk) open the
893	        // record the next chunk or end of stream will close.
894	        if !rest.is_empty() {
895	            self.sink.record_bytes(rest);
896	            self.open = true;
897	        }
898	    }
899	
900	    /// Finish the stream and give back the sink.
901	    fn finish(mut self) -> S {
902	        if self.open {
903	            self.sink.tail_end();
904	        }
905	        self.sink
906	    }
