908	    /// Convenience for callers that already hold the whole input: divide it in
909	    /// one pass.
910	    fn scan(self, data: &[u8]) -> S {
911	        let mut scanner = self;
912	        scanner.feed(data);
913	        scanner.finish()
914	    }
915	}
