917	/// Divide a complete batch into records on LF (0x0a), per the shared rule
918	/// documented on [`RecordScanner`]. The separator is not part of any record; a
919	/// trailing LF terminates the last record without adding an empty one; an empty
920	/// file yields zero records and a file containing one LF yields one empty
921	/// record.
922	#[doc(hidden)]
923	pub fn split_records(data: &[u8]) -> Vec<&[u8]> {
924	    /// Sink for the whole-batch case: content runs of one record are stitched
925	    /// back into slice positions. A run never crosses a chunk boundary here
926	    /// (the whole batch is one feed), but every record goes through the same
927	    /// content/end events as the streaming path.
928	    struct CollectRecords<'a> {
929	        data: &'a [u8],
930	        records: Vec<&'a [u8]>,
931	        /// Start offset of the record currently in progress. `None` until the
932	        /// record actually receives content: a record exists only once it has
933	        /// content or is terminated by an LF, so an empty input stays empty.
934	        start: Option<usize>,
935	        pos: usize,
