937	
938	    impl<'a> RecordSink for CollectRecords<'a> {
939	        fn record_bytes(&mut self, bytes: &[u8]) {
940	            // The scanner only calls this with non-empty content; the first run
941	            // of a record opens it at the byte it starts at.
942	            if self.start.is_none() {
943	                self.start = Some(self.pos);
944	            }
945	            self.pos += bytes.len();
946	        }
947	
948	        fn record_end(&mut self) {
949	            // Termination by LF always closes a record, even an empty one.
950	            let start = self.start.take().unwrap_or(self.pos);
951	            self.records.push(&self.data[start..self.pos]);
952	            self.pos += 1; // the terminating LF
953	        }
954	
955	        fn tail_end(&mut self) {
956	            // Only reached when content without a trailing LF is open.
957	            let start = self.start.take().expect("tail_end implies open content");
958	            self.records.push(&self.data[start..self.pos]);
959	        }
960	    }
