998	/// Construct the RFC 6962 Merkle tree over a batch. This is the SINGLE place
999	/// that maintains the tree-construction rules: both `root` (via `mth`) and
1000	/// `prove` (via `root_and_path`) build their leaves and subtrees here, so the
1001	/// two commands can never disagree on how a batch is shaped or hashed.
1002	///
1003	/// ```text
1004	/// MTH([])      = SHA-256("")
1005	/// MTH([d])     = SHA-256(0x00 || d)
1006	/// MTH(d0..dn)  = SHA-256(0x01 || MTH(d0..dk) || MTH(dk..dn))
1007	/// ```
1008	///
1009	/// with k the largest power of two strictly smaller than n. Uneven batches
1010	/// are handled by the recursion itself: no leaf is duplicated and no empty
1011	/// record is appended to round the size up to a power of two.
1012	///
1013	/// `target` selects the one leaf a membership proof is built for:
1014	///
1015	/// ```text
1016	/// PATH(m, [d0]) = []
1017	/// PATH(m, [d0..d(n-1)]) = PATH(m, [d0..d(k-1)]) + MTH([dk..d(n-1)])   if m < k
1018	///                       = PATH(m, [dk..d(n-1)]) + MTH([d0..d(k-1)])   if m >= k
1019	/// ```
1020	///
1021	/// When `target` is `Some(m)`, the sibling subtree hashes on the route from
1022	/// leaf `m` to the root are appended to `path` in leaf-to-root order
1023	/// (RFC 6962 section 2.1.1); the reindexed `Some(m - k)` follows the audited
1024	/// leaf into whichever subtree contains it, while the sibling subtree is
1025	/// built with `None`. With `None` only the root is built. Every leaf hash and
1026	/// every interior hash is computed exactly once in either mode, so producing
1027	/// a proof costs the same 2n - 1 SHA-256 invocations as the root alone.
1028	fn build_tree(
1029	    leaves: &[&[u8]],
1030	    target: Option<usize>,
1031	    path: &mut Vec<[u8; 32]>,
1032	) -> [u8; 32] {
1033	    match leaves.len() {
1034	        0 => sha256(&[]),
1035	        1 => leaf_hash(leaves[0]),
1036	        n => {
1037	            // Largest power of two strictly smaller than n.
1038	            let k = 1usize << (usize::BITS - 1 - (n - 1).leading_zeros());
1039	            let (left_leaves, right_leaves) = leaves.split_at(k);
1040	            match target {
1041	                // The audited leaf is in the left subtree; the right subtree
1042	                // hash is this level's sibling on the leaf-to-root path.
1043	                Some(m) if m < k => {
1044	                    let left = build_tree(left_leaves, Some(m), path);
1045	                    let right = build_tree(right_leaves, None, path);
1046	                    path.push(right);
1047	                    node_hash(&left, &right)
1048	                }
1049	                // The audited leaf is in the right subtree; reindex it
1050	                // relative to that subtree and take the left subtree as the
1051	                // sibling.
1052	                Some(m) => {
1053	                    let left = build_tree(left_leaves, None, path);
1054	                    let right = build_tree(right_leaves, Some(m - k), path);
1055	                    path.push(left);
1056	                    node_hash(&left, &right)
1057	                }
1058	                // No audited leaf: both subtrees are plain root constructions.
1059	                None => {
1060	                    let left = build_tree(left_leaves, None, path);
1061	                    let right = build_tree(right_leaves, None, path);
1062	                    node_hash(&left, &right)
1063	                }
1064	            }
1065	        }
1066	    }
1067	}
