1101	/// Incremental RFC 6962 Merkle Tree Hash over an LF-separated byte stream.
1102	///
1103	/// Bytes are fed through [`RootStream::feed`] in chunks of any size; how many
1104	/// bytes one read returns is meaningless to the result, and a record that
1105	/// spans any number of chunks is hashed in full. The LF/empty-record/trailing
1106	/// rule is applied by the shared [`RecordScanner`], exactly as
1107	/// [`split_records`] applies it to a whole batch, and the tree is folded with
1108	/// the same largest-power-of-two split as `build_tree`, so
1109	/// [`RootStream::finish`] returns exactly `mth(&split_records(whole))` for the
1110	/// concatenation `whole` of everything fed.
1111	///
1112	/// Memory use is the read buffer plus a small fixed amount and at most 64
1113	/// subtree hashes (one per bit of the record count): nothing grows with the
1114	/// number of bytes fed or with the length of any single record.
1115	#[doc(hidden)]
1116	pub struct RootStream {
1117	    /// The shared divider, feeding this stream's hashing sink.
1118	    scanner: RecordScanner<StreamSink>,
1119	}
