1121	/// [`RecordSink`] for the streaming root: hash content into the open leaf and
1122	/// fold one leaf per finished record into the subtree stack.
1123	struct StreamSink {
1124	    /// Hasher for the record currently being accumulated, primed with 0x00.
1125	    /// It stays primed even before any content arrives, so an LF-terminated
1126	    /// empty record hashes to SHA-256(0x00).
1127	    leaf: Sha256,
1128	    /// Completed subtree hashes, bottom to top in strictly decreasing height;
1129	    /// entry i covers 2^height consecutive leaves. Together the entries are
1130	    /// the binary decomposition of the record count so far, which is exactly
1131	    /// the shape the recursive largest-power-of-two split produces.
1132	    subtrees: Vec<([u8; 32], u32)>,
1133	}
