1161	    /// subtree stack, merging completed subtrees of equal height so the stack
1162	    /// always holds the largest complete subtrees on the left.
1163	    fn finish_record(&mut self) {
1164	        let leaf = std::mem::replace(&mut self.leaf, new_leaf_hasher()).finalize();
